import './style.css';

type PortAuthentication = {control:'force-authorized'|'auto'|'force-unauthorized';method:string;host_mode:string;fallback_no_supplicant:boolean;fallback_reject:boolean};
type AuthSession = {id:string;port_id:string;mac:string;method:string;vid:number;source:string;started_ms:number;last_activity_ms:number|null;in_packets:number;in_octets:number;lease_deadline_ms:number|null;idle_deadline_ms:number|null;reauthentication_deadline_ms:number|null};
type AccessResponse = {nas_code:number;attributes:{name:string;status:'absent'|'present'|'invalid';value?:number}[];omitted:{name:string;count:number}[]};
type AuthClient = {port_id:string;mac:string;status:string;reason?:string;method?:string;session_id?:string;response?:AccessResponse|null};
type Source = {id?:string;mac:string;tag:number|'untagged';initial_delay_ms:number;interval_ms:number;octets:number;supplicant?:any};
type Endpoint = {id:string;name:string;active:boolean;sources:Source[];metadata:Record<string,string>};
type Port = {authentication:PortAuthentication;id:string;name:string;alias:string;bridge_port:number;if_index:number;admin_up:boolean;mode:string;shared_partner:boolean;forced_down:boolean;speed:number;mtu:number;pvid:number;admitted:number[];untagged:number[];forbidden:number[];link_notifications:boolean;carrier:boolean;operational_up:boolean;attachments:string[];learned_count:number;counters:Record<string,number>};
type AdvanceOperation = {id:string;status:string;start_ms:number;target_ms:number;reached_ms:number;waiting_reason:string|null};
type State = {radius:any;advance:AdvanceOperation|null;authentication_sessions:AuthSession[];authentication_clients:AuthClient[];revision:number;configuration_revision:number;simulation_ms:number;uptime:number;paused:boolean;ports:Record<string,Port>;endpoints:Record<string,Endpoint>;vlans:Record<string,{vid:number;name:string;fdb_id:number}>;attachments:Record<string,string>;fdb:any[];switch:any;snmp:any;snmp_status:any;credentials:Record<string,any>;groups:Record<string,any>;targets:Record<string,any>;views:Record<string,any>;counters:any;warning:string|null};
let state:State, csrf='', page='overview', selected='', events:any[]=[], search='', ready=false;
const disconnecting=new Set<string>();
const app=document.querySelector<HTMLDivElement>('#app')!;
const dialog=document.querySelector<HTMLDialogElement>('#dialog')!;
const esc=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const values=<T>(o:Record<string,T>)=>Object.values(o);
const duration=(ms:number)=>`${Math.floor(ms/3600000).toString().padStart(2,'0')}:${Math.floor(ms/60000%60).toString().padStart(2,'0')}:${Math.floor(ms/1000%60).toString().padStart(2,'0')}`;
const pill=(label:string,style='')=>`<span class="pill ${style}">${esc(label)}</span>`;
const button=(label:string,action:string,id='',style='')=>`<button id="control-${esc(action)}-${esc(id||'new')}" class="${style}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const input=(label:string,name:string,value:unknown='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const check=(label:string,name:string,value:boolean)=>`<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const select=(label:string,name:string,options:string)=>`<label>${label}<select name="${name}">${options}</select></label>`;
const opt=(value:unknown,label:unknown,chosen=false)=>`<option value="${esc(value)}" ${chosen?'selected':''}>${esc(label)}</option>`;
const blank=(title:string,detail:string,action='')=>`<div class="empty"><div class="empty-icon">⌁</div><h3>${title}</h3><p>${detail}</p>${action}</div>`;

async function api(path:string,method='GET',data?:unknown){
  const response=await fetch('/api/v1'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});
  const json=await response.json();
  if(!response.ok){if(response.status===401){ready=false;void authenticate();}throw Error(typeof json.detail==='string'?json.detail:JSON.stringify(json.detail));}
  return json;
}
function toast(message:string,error=false){const el=document.querySelector<HTMLDivElement>('#toast')!;el.textContent=message;el.className=error?'show error':'show';setTimeout(()=>el.className='',4500);}
async function refresh(){state=await api('/state');events=(await api('/events?limit=2000')).events;render();}
async function write(path:string,method:string,data:any={},revision?:number){
  const current=revision??state.configuration_revision;
  const result=await api(path,method,{...data,expected_configuration_revision:current});
  await refresh();return result;
}
function dismissForm(){const f=dialog.querySelector('form');dialog.close();f?.reset();dialog.replaceChildren();}
function form(title:string,content:string,save:(f:HTMLFormElement)=>Promise<void|string>,label='Save changes'){
  dialog.innerHTML=`<form><div class="dialog-head"><div class="eyebrow">SWITCH LAB</div><h2>${title}</h2><button type="button" class="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${content}</div><p class="form-error" role="alert"></p><footer><button type="button" class="cancel">Cancel</button><button class="primary" type="submit">${label}</button></footer></form>`;
  dialog.querySelector('.close')!.addEventListener('click',dismissForm);dialog.querySelector('.cancel')!.addEventListener('click',dismissForm);dialog.oncancel=e=>{e.preventDefault();dismissForm();};
  const revision=state?.configuration_revision;
  dialog.querySelector('form')!.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget as HTMLFormElement;const submit=f.querySelector<HTMLButtonElement>('[type=submit]')!;submit.disabled=true;
    try{const message=await save(f);if(dialog.open&&dialog.contains(f)){dismissForm();toast(message??'Changes saved');}}catch(err){if(dialog.contains(f))f.querySelector('.form-error')!.textContent=(err as Error).message;}finally{submit.disabled=false;}};
  const currentForm=dialog.querySelector('form')!;dialog.addEventListener('close',()=>{if(!dialog.open&&dialog.contains(currentForm)){currentForm.reset();dialog.replaceChildren();}},{once:true});dialog.dataset.revision=String(revision);dialog.showModal();
}
const data=(f:HTMLFormElement)=>Object.fromEntries(new FormData(f));
const rev=()=>Number(dialog.dataset.revision);

async function authenticate(){
  const auth=await api('/auth/status');csrf=auth.csrf_token??'';
  if(auth.authenticated){ready=true;await refresh();return;}
  app.innerHTML=`<div class="auth-shell"><div class="auth-art"><div class="brand">▦ <strong>switch<span>lab</span></strong></div><div><h1>Switch Lab</h1><p>Ethernet switch management simulation with ports, endpoints, VLANs and SNMP.</p><div class="art-ports">${Array.from({length:24},(_,i)=>`<i class="${i%3===0?'on':''}"></i>`).join('')}</div></div><small>VENDOR-NEUTRAL · NO PACKET FORWARDING</small></div><div class="auth-form"><div class="eyebrow">${auth.setup_required?'FIRST-RUN SETUP':'ADMINISTRATOR ACCESS'}</div><h2>${auth.setup_required?'Create administrator':'Sign in'}</h2><p>${auth.setup_required?'Set the administrator password for this instance.':'Use your administrator password to continue.'}</p><form>${input('Administrator password','password','','password',`required maxlength="1024" autocomplete="${auth.setup_required?'new-password':'current-password'}"`)}<p class="form-error" role="alert"></p><button class="primary" type="submit">${auth.setup_required?'Create administrator':'Sign in'} <span>→</span></button></form></div></div>`;
  app.querySelector('form')!.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget as HTMLFormElement;try{const result=await api(auth.setup_required?'/auth/setup':'/auth/login','POST',data(f));csrf=result.csrf_token;ready=true;await refresh();}catch(err){f.querySelector('.form-error')!.textContent=(err as Error).message;}};
}

const simulation=()=>document.querySelector<HTMLDetailsElement>('#simulation');
function closeSimulation(focus=false){const el=simulation();if(el?.open){el.open=false;if(focus)el.querySelector<HTMLElement>('summary')!.focus();}}
function render(){
  if(!ready||dialog.open)return;
  const radiusOpen=[...document.querySelectorAll<HTMLDetailsElement>('#radius-config details[open], .port-detail details[open]')].map(el=>el.id);
  const disclosure=simulation(),open=disclosure?.open;
  const focus=disclosure?.contains(document.activeElement)||document.activeElement?.closest('#radius-config,.port-detail,nav')?document.activeElement?.id:undefined;
  const position={x:scrollX,y:scrollY};
  const ports=values(state.ports),eps=values(state.endpoints),up=ports.filter(p=>p.operational_up).length;
  if(!selected)selected=ports[0]?.id;
  const navigation=[['overview','▦','Switch overview'],['endpoints','◈','Endpoint library'],['vlans','▤','VLANs'],['fdb','≋','Learned addresses'],['interfaces','⇄','Interfaces'],['events','◷','Event history'],['snmp','⇆','SNMP'],['radius','◉','RADIUS'],['settings','⚙','Settings']];
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/">▦ <strong>switch<span>lab</span></strong></a><div class="workspace"><span class="live-dot"></span><div>${esc(state.switch.name)}<small>Single-switch workspace</small></div></div><div class="nav-label">WORKSPACE</div><nav>${navigation.map(([id,icon,label])=>`<button id="nav-${id}" data-action="nav" data-id="${id}" aria-current="${page===id?'page':'false'}" class="${page===id?'active':''}"><span>${icon}</span>${label}${id==='endpoints'?`<b>${eps.length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-status">${pill(state.snmp_status.listener_ready?'SNMP online':'SNMP setup',state.snmp_status.listener_ready?'green':'amber')}<p>Generic switch emulator<br>No Ethernet forwarding</p></div>${button('↗ Export scenario','export')}${button('↙ Import scenario','import')}${button('Sign out','logout')}</div></aside><main><header><div class="breadcrumb">Workspace <span>/</span> ${navigation.find(x=>x[0]===page)?.[2]}</div><div class="header-controls"><div class="top-status"><span class="live-dot"></span> API connected <span class="divider"></span> v0.1.0</div><details id="simulation" ${open?'open':''}><summary id="simulation-summary">Simulation</summary><div class="simulation-panel"><div class="simulation-time"><code>${duration(state.simulation_ms)}</code><span>${state.paused?'Paused':'Running'}</span></div><div class="actions"><button id="simulation-toggle" data-action="${state.paused?'resume':'pause'}" ${state.paused&&state.advance?.status==='waiting'?'disabled':''}>${state.paused?'▶ Resume':'Ⅱ Pause'}</button><button id="simulation-second" data-action="advance1" ${state.advance?.status==='waiting'?'disabled':''}>+1s</button><button id="simulation-advance" data-action="advance" ${state.advance?.status==='waiting'?'disabled':''}>Advance…</button></div>${state.advance?.status==='waiting'?`<div class="advance-progress" role="status"><p>Reached ${duration(state.advance.reached_ms)} / ${duration(state.advance.target_ms)}<small>Waiting for ${esc(state.advance.waiting_reason)}</small></p><button id="simulation-cancel" data-action="cancel-advance" data-id="${esc(state.advance.id)}">Cancel remaining advance</button></div>`:''}</div></details></div></header><div class="page"><div class="page-heading"><div><div class="eyebrow">NETWORK SIMULATION</div><h1>${navigation.find(x=>x[0]===page)?.[2]}</h1><p>${({overview:'Ports, attachments and learned addresses.',endpoints:'Reusable definitions, independent from observed learning.',vlans:'Independent VLAN learning. Explicit admission on every port.',fdb:'Switch-observed addresses, including cached historical entries.',interfaces:'Stable interface indexes and synthetic ingress counters.',events:'Committed changes and notification delivery attempts.',snmp:'Identity, incoming access and notifications.',radius:'Authentication, certificates and access services.',settings:'Switch identity, learning and management.'} as any)[page]}</p></div></div>
  ${!state.switch.identity.sys_object_id?`<div class="notice"><span>◉</span><div><strong>SNMP disabled: configure a system object ID</strong><small>Your simulation is available. Add an identity and explicit read or write access to enable incoming SNMP.</small></div>${button('Configure SNMP →','nav','snmp','text-button')}</div>`:''}
  ${state.snmp_status.documentation_identity?'<div class="notice warning">Documentation-only identity selected. This example value is not an assigned operational identity.</div>':''}
  ${state.warning?`<div class="notice warning">${esc(state.warning)}</div>`:''}
  ${state.counters.notification_drops||state.counters.learning_discards?`<div class="notice warning">Capacity warning: ${state.counters.notification_drops} notifications dropped; ${state.counters.learning_discards} learning attempts rejected.</div>`:''}
  ${page==='overview'?overview(ports,eps,up):page==='endpoints'?endpoints():page==='vlans'?vlans():page==='fdb'?fdb():page==='interfaces'?interfaces():page==='events'?eventHistory():page==='snmp'?snmpSettings():page==='radius'?radiusSettings():generalSettings()}
  <div class="page-foot"><span><span class="live-dot"></span> State revision ${state.revision}</span><span>Management uptime ${duration(state.uptime*10)}</span></div></div></main></div>`;
  for(const el of document.querySelectorAll<HTMLDetailsElement>('#radius-config details[id]')){const summary=el.querySelector<HTMLElement>('summary');if(summary&&!summary.id)summary.id=el.id+'-toggle';}
  for(const id of radiusOpen){const el=document.getElementById(id) as HTMLDetailsElement|null;if(el)el.open=true;}
  if(focus)document.getElementById(focus)?.focus({preventScroll:true});
  window.scrollTo(position.x,position.y);
}
function overview(ports:Port[],eps:Endpoint[],up:number){const p=state.ports[selected];return `<div class="stats">${[['PORTS UP',`${up}`,`of ${ports.length} configured ports`],['ATTACHED ENDPOINTS',`${Object.keys(state.attachments).length}`,`${eps.length} saved in library`],['LEARNED ADDRESSES',`${state.fdb.length}`,`capacity ${state.switch.fdb_limit.toLocaleString()}`],['ACTIVE VLANS',`${Object.keys(state.vlans).length}`,`legacy view: VLAN ${state.switch.legacy_vlan}`]].map(([label,v,detail])=>`<div class="stat"><label>${label}</label><strong>${v}</strong><small>${detail}</small></div>`).join('')}</div><div class="overview-columns"><section class="card port-card"><div class="card-head"><div><h2>Port map</h2><p>${ports.length} × configured Ethernet ports</p></div><span class="legend"><i></i> Up <i class="down"></i> Down</span></div><div class="switch-chassis"><div class="chassis-label"><b>${esc(state.switch.name)}</b><span>BRIDGE ${esc(state.switch.base_mac)}</span></div><div class="port-grid">${ports.map(p=>`<button aria-label="Port ${p.bridge_port}, ${p.operational_up?'up':'down'}" data-action="select-port" data-id="${p.id}" class="port ${p.operational_up?'up':''} ${p.forced_down?'fault':''} ${selected===p.id?'selected':''}"><span class="port-number">${String(p.bridge_port).padStart(2,'0')}</span><div class="jack"><i></i><b></b></div><small>${p.mode==='shared'?'SHARED':'DIRECT'}</small></button>`).join('')}</div><div class="chassis-foot"><span>● SYSTEM</span><span>MANAGEMENT SIMULATION</span><span>${state.paused?'Ⅱ PAUSED':'● RUNNING'}</span></div></div><div class="card-caption">Select a port to inspect its link, VLAN membership and attachments.</div></section>${p?portDetails(p):''}<section class="card"><div class="card-head compact"><h2>Recent activity</h2>${button('View history →','nav','events','text-button')}</div>${events.length?eventTable(events.slice(-4).reverse()):blank('No recent activity','Add an endpoint and attach it to a port.')}</section></div>`;}
function portDetails(p:Port){const fact=(label:string,value:unknown)=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;return `<section class="card port-detail" aria-label="Selected port details"><div class="card-head port-heading"><div><div class="eyebrow">PORT ${String(p.bridge_port).padStart(2,'0')}</div><h2>${esc(p.name)}</h2><div class="port-meta">Interface ${p.if_index} · ${p.speed/1e9} Gbit/s · ${p.learned_count} learned addresses</div></div><div class="actions">${pill(p.operational_up?'Link up':'Link down',p.operational_up?'green':'')}${button('Configure port','edit-port',p.id)}</div></div><div class="detail-body"><div class="port-properties"><section class="port-fact-group"><h3>Link</h3><dl>${fact('Admin / carrier',`${p.admin_up?'Enabled':'Disabled'} / ${p.carrier?'Present':'Absent'}`)}${fact('Mode',p.mode)}${p.mode==='shared'?fact('Shared link partner',p.shared_partner?'Present':'Absent'):''}${fact('Forced link fault',p.forced_down?'Active':'Off')}</dl></section><section class="port-fact-group"><h3>Configured VLANs</h3><dl>${fact('Ingress VLAN (PVID)',p.pvid)}${fact('Admitted VLANs',p.admitted.join(', '))}${fact('Untagged VLANs',p.untagged.join(', ')||'—')}${fact('Forbidden VLANs',p.forbidden.join(', ')||'—')}</dl><p class="hint">Saved port policy. Effective client VLANs appear under Port access.</p></section></div><section class="port-attachments"><div class="subsection-head"><h3>Attached endpoints <span class="count">${p.attachments.length}</span></h3>${button('+ Attach endpoint','attach-port',p.id)}</div>${p.attachments.map(id=>`<div class="attached"><div><b>${esc(state.endpoints[id].name)}</b><small>${state.endpoints[id].sources.length} sources · ${state.endpoints[id].active?'Active':'Silent'}</small></div><div>${button('Edit','edit-endpoint',id)}${button('Supplicants','supplicants',id)}<button data-action="detach" data-id="${esc(id)}" aria-label="Disconnect ${esc(state.endpoints[id].name)} (${esc(id)})" ${disconnecting.has(id)?'disabled':''}>Disconnect</button></div></div>`).join('')||'<p class="muted">No endpoint attached.</p>'}</section><section class="port-authentication">${authenticationDetail(p)}</section></div></section>`;}
function responseAttributes(response:AccessResponse|null){if(!response)return '';return `<p>Authenticated NAS response: ${esc(response.nas_code===2?'Access-Accept':response.nas_code===3?'Access-Reject':String(response.nas_code))}. This is separate from applying access policy.</p><dl class="facts">${response.attributes.map((a:any)=>`<div><dt>${esc(a.name)}</dt><dd>${a.status==='present'?esc(a.value):esc(a.status)}</dd></div>`).join('')}${response.omitted.map((a:any)=>`<div><dt>${esc(a.name)}</dt><dd>Present × ${esc(a.count)}; value omitted</dd></div>`).join('')}</dl>`;}
function authenticationHistory(p:Port,mac:string){const groups=new Map<string,any>();for(const e of events.filter(e=>e.port_id===p.id&&(!e.mac||e.mac===mac)&&(/^(authentication|pae)-/.test(e.kind)))){const key=JSON.stringify([e.kind,e.mac??null,e.reason??null,e.response??null]);const prior=groups.get(key);groups.set(key,{...e,count:(prior?.count??0)+1,first_id:prior?.first_id??e.id});}const rows=[...groups.values()].sort((a,b)=>b.id-a.id).slice(0,20);return `<details id="auth-history-${esc(p.id)}-${esc(mac)}"><summary id="auth-history-toggle-${esc(p.id)}-${esc(mac)}">Authentication history (${rows.length} groups)</summary>${rows.length?rows.map(e=>`<div class="setting-row"><div><b>${esc(e.kind)}${e.count>1?` × ${e.count}`:''}</b><small>${duration(e.simulation_ms)} · ${e.mac?'Client':'Port'} scope${e.reason?' · '+esc(e.reason):''}</small>${e.response?`<details id="auth-response-${esc(p.id)}-${esc(mac)}-${e.first_id}"><summary id="auth-response-toggle-${esc(p.id)}-${esc(mac)}-${e.first_id}">Response attributes</summary>${responseAttributes(e.response)}</details>`:''}</div></div>`).join(''):'<p class="muted">No retained authentication events.</p>'}</details>`;}
function authenticationDetail(p:Port){
  const sessions=state.authentication_sessions.filter(s=>s.port_id===p.id);
  const clients=state.authentication_clients.filter(c=>c.port_id===p.id);
  const addresses=[...new Set([...p.attachments.flatMap(id=>state.endpoints[id].sources.map(s=>s.mac)),...clients.map(c=>c.mac),...sessions.map(s=>s.mac)])];
  const policy=p.authentication;

  return `<div class="subsection-head"><div><h3>Port access</h3><p class="hint">Authorization is independent of physical link state.</p></div><div class="access-policy">${pill(policy.control)}${pill(policy.host_mode)}${pill(policy.method)}</div></div>${addresses.length?`<div class="table-wrap"><table class="authentication-clients"><thead><tr><th>Client MAC</th><th>Access</th><th>Method / reason</th><th>Effective VLAN</th><th>Session</th><th>Admitted packets</th></tr></thead><tbody>${addresses.map(mac=>{
    const client=clients.find(c=>c.mac===mac),session=sessions.find(s=>s.mac===mac)??(policy.host_mode==='multi-host'?sessions[0]:undefined);
    const status=policy.control==='force-authorized'?'Force authorized':policy.control==='force-unauthorized'?'Force unauthorized':session?'Authorized':client?.status??'Waiting';
    return `<tr><td data-label="Client MAC"><code>${esc(mac)}</code></td><td data-label="Access">${pill(status,policy.control==='force-authorized'||session?'green':'')}</td><td data-label="Method / reason">${esc(session?.method??client?.method??'—')}<small>${esc(client?.reason??'')}</small>${client?.response?`<details id="current-response-${esc(p.id)}-${esc(mac)}"><summary id="current-response-toggle-${esc(p.id)}-${esc(mac)}">Response attributes</summary>${responseAttributes(client.response)}</details>`:''}${authenticationHistory(p,mac)}</td><td data-label="Effective VLAN">${session?`${session.vid}<small>${esc(session.source)}</small>`:policy.control==='force-authorized'?`${p.pvid}<small>Port default</small>`:'—'}</td><td data-label="Session">${session?`<code>${esc(session.id)}</code><small>Started ${duration(session.started_ms)}${session.mac!==mac?' · Shared service':''}</small><small>${session.lease_deadline_ms===null?'':`Session limit ${duration(session.lease_deadline_ms)} · `}${session.idle_deadline_ms===null?'':`Idle limit ${duration(session.idle_deadline_ms)}`}</small>${session.mac===mac?`<div class="session-actions">${button('Reauthenticate','radius-reauthenticate',session.id)}${button('Restart','radius-restart',session.id)}</div>`:''}`:'—'}</td><td data-label="Admitted packets">${session?`${session.in_packets}<small>Accounting: ${!state.radius.accounting.enabled?'disabled':`${state.radius.accounting_status.records.filter((r:any)=>r.session_id===session.id).length} queued`}</small>`:'—'}</td></tr>`;
  }).join('')}</tbody></table></div>`:'<p class="muted">No client sources on this port.</p>'}`;
}
function sourceConditions(e:Endpoint){const pid=state.attachments[e.id];if(!pid)return '';const p=state.ports[pid];const invalid=e.sources.filter(s=>{const session=p.authentication.control==='auto'?(state.authentication_sessions.find(x=>x.port_id===pid&&x.mac===s.mac)??(p.authentication.host_mode==='multi-host'?state.authentication_sessions.find(x=>x.port_id===pid):undefined)):undefined;const vid=session?.vid??(s.tag==='untagged'?p.pvid:s.tag);return !state.vlans[String(vid)]||p.forbidden.includes(vid)||(session?s.tag!=='untagged'&&s.tag!==vid:!p.admitted.includes(vid));});return invalid.length?pill(`${invalid.length} rejected VLAN source${invalid.length>1?'s':''}`,'amber'):'';}
function endpoints(){const eps=values(state.endpoints).filter(e=>`${e.name} ${e.sources.map(s=>s.mac).join(' ')}`.toLowerCase().includes(search.toLowerCase()));return `<section class="card"><div class="card-head"><div><h2>Endpoint library <span class="count">${values(state.endpoints).length}</span></h2><p>Configured metadata and sources</p></div><div class="actions"><input id="search" placeholder="Search name or MAC…" aria-label="Search endpoints" value="${esc(search)}">${button('+ New endpoint','new-endpoint','','primary')}</div></div>${eps.length?`<div class="table-wrap"><table><thead><tr><th>Endpoint</th><th>Source addresses</th><th>Activity</th><th>Attachment</th><th></th></tr></thead><tbody>${eps.map(e=>`<tr><td><b>${esc(e.name)}</b><small class="mono">${e.id.slice(0,8)}</small></td><td>${e.sources.slice(0,3).map(s=>`<div class="source-line"><code>${esc(s.mac)}</code>${pill(s.tag==='untagged'?'untagged':`VLAN ${s.tag}`)}</div>`).join('')||'<span class="muted">No sources</span>'}${e.sources.length>3?`<small>+${e.sources.length-3} more sources</small>`:''}${sourceConditions(e)}</td><td>${pill(e.active?'Active':'Silent',e.active?'green':'')}</td><td>${state.attachments[e.id]?button(esc(state.ports[state.attachments[e.id]].name),'attachment',e.id,'text-button'):button('Attach →','attachment',e.id,'text-button')}</td><td class="row-actions">${button('Edit','edit-endpoint',e.id)}${button('Supplicants','supplicants',e.id)}${button('Clone','clone',e.id)}${button('×','delete-endpoint',e.id,'danger')}</td></tr>`).join('')}</tbody></table></div>`:blank('No endpoints configured','Create an endpoint with one or more MAC sources, then connect it to a port.',button('+ Create endpoint','new-endpoint','','primary'))}</section>`;}
function vlans(){return `<section class="card"><div class="card-head"><div><h2>VLAN inventory</h2><p>Ingress PVID and untagged egress memberships are independent.</p></div>${button('+ Add VLAN','new-vlan','','primary')}</div><div class="table-wrap"><table><thead><tr><th>VLAN</th><th>Name</th><th>FDB ID</th><th>Admitted ports</th><th>Untagged ports</th><th>Forbidden ports</th><th>Learned</th><th></th></tr></thead><tbody>${values(state.vlans).sort((a,b)=>a.vid-b.vid).map(v=>`<tr><td>${pill(String(v.vid),v.vid===1?'green':'')}</td><td><b>${esc(v.name)}</b>${v.vid===1?'<small>Permanent default</small>':''}</td><td><code>${v.fdb_id}</code></td><td>${values(state.ports).filter(p=>p.admitted.includes(v.vid)).map(p=>p.bridge_port).join(', ')||'—'}</td><td>${values(state.ports).filter(p=>p.untagged.includes(v.vid)).map(p=>p.bridge_port).join(', ')||'—'}</td><td>${values(state.ports).filter(p=>p.forbidden.includes(v.vid)).map(p=>p.bridge_port).join(', ')||'—'}</td><td>${state.fdb.filter(r=>r.vid===v.vid).length}</td><td class="row-actions">${button('Rename','edit-vlan',String(v.vid))}${v.vid!==1?button('Delete','delete-vlan',String(v.vid),'danger'):''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function fdb(){return `<section class="card"><div class="card-head"><div><h2>Forwarding database <span class="count">${state.fdb.length}</span></h2><p>Age: ${state.switch.aging_seconds}s · BRIDGE-MIB scope: VLAN ${state.switch.legacy_vlan}</p></div>${button('Clear learning…','clear')}</div>${state.fdb.length?`<div class="table-wrap"><table><thead><tr><th>MAC address</th><th>VID</th><th>FDB ID</th><th>Bridge port</th><th>ifIndex</th><th>Last observed</th><th>Remaining age</th></tr></thead><tbody>${[...state.fdb].sort((a,b)=>a.vid-b.vid||a.mac.localeCompare(b.mac)).map(r=>`<tr><td><code>${esc(r.mac)}</code></td><td>${pill(String(r.vid))}</td><td>${r.fdb_id}</td><td>${r.bridge_port}</td><td>${r.if_index}</td><td><code>${duration(r.last_seen_ms)}</code></td><td><code>${(r.remaining_ms/1000).toFixed(1)}s</code></td></tr>`).join('')}</tbody></table></div>`:blank('Waiting for source activity','Attach an active endpoint to an up port with an admitted VLAN. Learning starts after its initial delay.',button('Open endpoint library →','nav','endpoints','primary'))}</section>`;}
function interfaces(){return `<section class="card"><div class="card-head"><div><h2>Interface counters</h2><p>Source events increment ingress counters. Polling never increments counters.</p></div></div><div class="table-wrap"><table><thead><tr><th>Interface</th><th>ifIndex / bridge</th><th>Admin</th><th>Operational</th><th>In octets</th><th>In unicast</th><th>In discards</th><th>Out octets</th></tr></thead><tbody>${values(state.ports).map(p=>`<tr><td>${button(esc(p.name),'edit-port',p.id,'text-button')}</td><td><code>${p.if_index} / ${p.bridge_port}</code></td><td>${p.admin_up?'Up':'Down'}</td><td>${pill(p.operational_up?'Up':'Down',p.operational_up?'green':'')}</td><td>${p.counters.in_octets.toLocaleString()}</td><td>${p.counters.in_ucast.toLocaleString()}</td><td>${p.counters.in_discards.toLocaleString()}</td><td>0</td></tr>`).join('')}</tbody></table></div></section>`;}
function eventTable(rows:any[]){return `<div class="table-wrap"><table class="events-table"><tbody>${rows.map(e=>`<tr><td><span class="event-dot ${e.kind==='linkUp'?'green':''}"></span></td><td><b>${esc(e.kind)}</b><small>${esc(e.mac??e.endpoint_id?.slice(0,8)??e.target_id?.slice(0,8)??'Switch state')}${e.vid?` · VLAN ${e.vid}`:''}</small></td><td>${e.status?pill(e.status,e.status==='sent'?'green':e.status.includes('failed')||e.status.includes('dropped')?'amber':''):''}</td><td class="muted mono">${duration(e.simulation_ms)}</td></tr>`).join('')}</tbody></table></div>`;}
function eventHistory(){return `<section class="card"><div class="card-head"><div><h2>Event history</h2><p>Latest 2,000 events. “Sent” means handed to UDP; delivery is not acknowledged.</p></div><span class="muted">${events.length} retained</span></div>${eventTable([...events].reverse())}</section>`;}
const defaultAccess=()=>({polling:{enabled:false,view_id:'all',networks:[] as string[]},writing:{enabled:false,view_id:null as string|null,networks:[] as string[]}});
const policyOf=(c:any)=>c?.version==='3'?state.groups[c.group_id]:c;
const accessMode=(p:any)=>p?.polling.enabled?(p.writing.enabled?'read-write':'read'):(p?.writing.enabled?'write':'none');
const accessLabel=(p:any)=>({'none':'None (traps only)','read':'Read','read-write':'Read/write','write':'Write only'}[accessMode(p)]!);
function listenerStatus(){
  const s=state.snmp_status;
  const ordinary=['ready','initializing','credentials_required','set_access_required','identity_required','disabled'];
  const error=[s.reason,s.writing_reason].find(x=>x&&!ordinary.includes(x));
  if(s.listener_ready)return error?`Listening · ${error}`:'Listening';
  if(!state.switch.identity.sys_object_id)return 'Identity required';
  if(!state.snmp.enabled)return 'Disabled';
  if(error)return error;
  if(s.reason==='credentials_required'&&s.writing_reason==='set_access_required')return 'Incoming access required';
  return 'Initializing';
}
function credentialSection(version:string){
  const users=version==='3',rows=values(state.credentials).filter(c=>c.version===version);
  return `<section class="card"><div class="card-head"><div><h2>${users?'SNMPv3 users':'SNMPv2c communities'}</h2><p>${users?'USM identities and group membership.':'Community-based incoming access.'}</p></div>${button(users?'+ User':'+ Community',users?'user':'credential')}</div><div class="detail-body">${rows.map(c=>`<div class="setting-row"><div><b>${esc(c.label)}</b><small>${users?`${esc(c.username)} · ${esc(c.security_level)} · `:''}${c.enabled?'enabled':'disabled'}</small><small>${users?`${esc(state.groups[c.group_id]?.label??'No group')} · `:''}${esc(accessLabel(policyOf(c)))}</small></div><div>${button('Edit','credential',c.id)}${button('Delete','delete-credential',c.id,'danger')}</div></div>`).join('')||`<p class="muted">No ${users?'users':'communities'} configured.</p>`}</div></section>`;
}
function generalSettings(){const s=state.switch;return `<div class="settings-grid"><section class="card"><div class="card-head"><div><h2>Switch settings</h2><p>Name, location and learning behavior.</p></div>${button('Edit','switch-settings')}</div><div class="detail-body">${[['System name',s.name],['Contact',s.contact||'—'],['Location',s.location||'—'],['Bridge base MAC',s.base_mac],['MAC aging',`${s.aging_seconds}s`],['Dynamic FDB capacity',s.fdb_limit]].map(([label,value])=>`<div class="kv"><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Management reboot</h2><p>Clear learning, counters and simulation time.</p></div></div><div class="detail-body"><p class="hint">Configuration and attachments are preserved. Source delays restart. A paused lab remains paused.</p>${button('Reboot switch…','reboot','','danger')}</div></section></div>`;}
function snmpSettings(){const s=state.switch;return `<div class="settings-grid"><section class="card"><div class="card-head"><div><h2>SNMP identity</h2><p>Advertised identity and notification capacity.</p></div>${button('Edit','identity')}</div><div class="detail-body"><div class="kv"><span>System object ID (sysObjectID)</span><code>${esc(s.identity.sys_object_id??'Not configured')}</code></div><div class="kv"><span>Description</span><b>${esc(s.identity.sys_descr)}</b></div><div class="kv"><span>Legacy VLAN</span><b>${s.legacy_vlan}</b></div><div class="kv"><span>Notification queue capacity</span><b>${s.queue_limit}</b></div><p class="hint">System name, contact and location are edited in Settings.</p></div></section><section class="card"><div class="card-head"><div><h2>SNMP service</h2><p>Incoming listener and outgoing trap transport.</p></div>${button('Configure','snmp')}</div><div class="detail-body"><div class="kv"><span>Listener status</span>${pill(listenerStatus(),state.snmp_status.listener_ready?'green':'amber')}</div><div class="kv"><span>Trap transport</span>${pill(state.snmp_status.notifications_ready?'ready':'not ready',state.snmp_status.notifications_ready?'green':'amber')}</div><div class="kv"><span>Listener</span><code>${esc(state.snmp.host)}:${state.snmp.port}/udp</code></div><div class="kv"><span>Engine ID</span><code>${esc(state.snmp_status.engine_id??'Not initialized')}</code></div><div class="kv"><span>Engine boots</span><b>${state.snmp_status.engine_boots??'—'}</b></div><p class="hint">SNMPv2c and v3 modes without privacy transmit data without encryption.</p></div></section>${credentialSection('2c')}${credentialSection('3')}<section class="card"><div class="card-head"><div><h2>SNMPv3 groups</h2><p>Shared incoming access for member users.</p></div>${button('+ Group','group')}</div><div class="detail-body">${values(state.groups).map(g=>`<div class="setting-row"><div><b>${esc(g.label)}</b><small>${esc(accessLabel(g))} · minimum ${esc(g.minimum_security_level)}</small><small>${values(state.credentials).filter(c=>c.version==='3'&&c.group_id===g.id).length} members</small></div><div>${button('Edit','group',g.id)}${button('Delete','delete-group',g.id,'danger')}</div></div>`).join('')||'<p class="muted">No groups configured.</p>'}</div></section><section class="card"><div class="card-head"><div><h2>Notification targets</h2><p>Standard coldStart, linkUp and linkDown traps.</p></div>${button('+ Target','target')}</div><div class="detail-body">${values(state.targets).map(t=>`<div class="setting-row"><div><b>${esc(t.address)}:${t.port}</b><small>${esc(t.types.join(', '))}</small></div><div>${button('Test','test-target',t.id)}${button('Edit','target',t.id)}${button('×','delete-target',t.id,'danger')}</div></div>`).join('')||'<p class="muted">No notification destinations configured.</p>'}</div></section><section class="card"><div class="card-head"><div><h2>OID views</h2><p>Read and write access select views independently. Walks traverse accessible objects only.</p></div>${button('+ View','view')}</div><div class="detail-body">${values(state.views).map(v=>`<div class="setting-row"><div><b>${esc(v.name)}</b><small class="mono">${esc(v.includes.join(', '))}</small></div><div>${button('Edit','view',v.id)}${button('×','delete-view',v.id,'danger')}</div></div>`).join('')}</div></section></div>`;}


function radiusSettings(){const r=state.radius;return `<section id="radius-config" class="card radius-config"><div class="card-head"><div><h2>RADIUS access</h2><p>Port authentication and copied client supplicants.</p></div>${button('Settings','radius-settings')}</div><div class="detail-body">${!r.eap_capability.available?`<p class="hint">EAP helper: ${esc(r.eap_capability.reason)}. Linux native or Docker supplies the managed peer; MAB is independent.</p>`:''}${!r.nas_identity_ready?'<p class="hint warning">The switch name cannot be used as a NAS identifier. Set an explicit 1–253-byte UTF-8 identifier.</p>':''}<details id="radius-servers"><summary>Authentication servers (${r.servers.length})</summary><div class="actions">${button('+ Server','radius-server')}</div>${r.servers.map((s:any,i:number)=>`<div class="setting-row"><div><b>${i+1}. ${esc(s.label)}</b><small>${esc(s.address)}:${s.port} · ${s.enabled?esc(r.server_status[s.id]?.status??'Not checked'):'Disabled'}</small></div><div>${button('Edit','radius-server',s.id)}${button('Delete','radius-server-delete',s.id,'danger')}</div></div>`).join('')||'<p class="muted">No authentication servers configured.</p>'}</details>${certificateSection()}<details id="radius-templates"><summary>Supplicant templates (${Object.keys(r.templates).length})</summary><div class="actions">${button('+ Template','radius-template')}</div>${values<any>(r.templates).map(t=>`<div class="setting-row"><div><b>${esc(t.label)}</b><small>${esc(t.profile.method)} · Revision ${t.revision}</small></div><div>${button('Edit','radius-template',t.id)}${button('Delete','radius-template-delete',t.id,'danger')}</div></div>`).join('')}</details>${radiusServiceSettings()}</div></section>`;}
function radiusServiceSettings(){const r=state.radius,a=r.accounting,d=r.dynamic_authorization;return `<details id="radius-accounting"><summary>Accounting · ${a.enabled?'Enabled':'Disabled'}</summary><div class="actions">${button('Accounting settings','accounting-settings')}${button('+ Accounting target','accounting-target')}</div><p class="hint">${r.accounting_status.queued} queued · ${Object.values<number>(r.accounting_status.drops).reduce((a,b)=>a+b,0)} dropped. Delivery is independent of access.</p>${a.targets.map((target:any,i:number)=>`<div class="setting-row"><div><b>${i+1}. ${esc(target.label)}</b><small>${esc(target.address)}:${target.port} · ${target.enabled?'Enabled':'Disabled'}</small></div><div>${button('Edit','accounting-target',target.id)}${button('Delete','accounting-target-delete',target.id,'danger')}</div></div>`).join('')}</details><details id="radius-dynamic"><summary>Dynamic authorization · ${r.dynamic_status.ready?'Listening':d.enabled?'Not ready':'Disabled'}</summary><div class="actions">${button('Dynamic authorization settings','dynamic-settings')}${button('+ Trusted sender','dynamic-sender')}</div><p class="hint">${esc(d.host)}:${d.port} · ${r.dynamic_status.cached} replay decisions · ${r.dynamic_status.pending} pending.${!r.dynamic_status.clock_safe?' DAS is waiting for the real clock to reach its replay-safety watermark.':''}${r.dynamic_status.reason?' '+esc(r.dynamic_status.reason):''}</p>${d.senders.map((sender:any)=>`<div class="setting-row"><div><b>${esc(sender.label)}</b><small>${esc(sender.address)} · ${sender.enabled?'Enabled':'Disabled'}</small></div><div>${button('Edit','dynamic-sender',sender.id)}${button('Delete','dynamic-sender-delete',sender.id,'danger')}</div></div>`).join('')}</details>`;}
function editAccountingSettings(){const a=state.radius.accounting;form('Accounting settings',`${check('Enable accounting','enabled',a.enabled)}${select('Interim updates','interim_mode',opt('server','Use valid server interval',a.interim_seconds===null)+opt('off','Disabled',a.interim_seconds===0)+opt('local','Local override',a.interim_seconds!==null&&a.interim_seconds>0))}${input('Local interim interval (simulation seconds)','interim_seconds',a.interim_seconds&&a.interim_seconds>0?a.interim_seconds:60,'number','min="60" max="1000000"')}<div class="form-grid">${input('Response timeout (real seconds)','response_timeout_seconds',a.response_timeout_seconds,'number','min="1" max="60" required')}${input('Attempts per target','attempts',a.attempts,'number','min="1" max="10" required')}${input('Retry backoff base (real seconds)','retry_backoff_seconds',a.retry_backoff_seconds,'number','min="0" max="30" required')}</div><p class="hint">A local interval overrides the server. Start, cumulative interim snapshots and Stop are sent in order; queued records retain their generation time and expire after 300 real seconds.</p>`,async f=>{const d=data(f);await write('/radius/accounting','PATCH',{enabled:!!d.enabled,interim_seconds:d.interim_mode==='server'?null:d.interim_mode==='off'?0:Number(d.interim_seconds),response_timeout_seconds:Number(d.response_timeout_seconds),attempts:Number(d.attempts),retry_backoff_seconds:Number(d.retry_backoff_seconds)},rev());});}
function editDynamicSettings(){const d=state.radius.dynamic_authorization;form('Dynamic authorization settings',`${check('Enable CoA and Disconnect listener','enabled',d.enabled)}<div class="form-grid">${input('Bind IP address','host',d.host,'text','required')}${input('UDP port','port',d.port,'number','min="1" max="65535" required')}</div><p class="hint">Only separately configured sender IPs and secrets are trusted. Requests require Message-Authenticator and Event-Timestamp within 300 real seconds. No SNMP or authentication-server setting enables this listener.</p>`,async f=>{const v=data(f);await write('/radius/dynamic','PATCH',{enabled:!!v.enabled,host:v.host,port:Number(v.port)},rev());});}
function editDynamicSender(id?:string){const s=state.radius.dynamic_authorization.senders.find((s:any)=>s.id===id);form(s?'Edit trusted dynamic sender':'Add trusted dynamic sender',`${input('Label','label',s?.label??'','text','required maxlength="80"')}${input('Sender IP address','address',s?.address??'','text','required')}${input(s?'Shared secret (blank = unchanged)':'Shared secret','secret','','password',s?'':'required')}${check('Enabled','enabled',s?.enabled??true)}<p class="hint">Trust follows the actual source IP, not a NAS identifier inside the packet.</p>`,async f=>{const d=data(f);await write('/radius/dynamic/senders','POST',{...(id?{id}:{}),label:d.label,address:d.address,secret:d.secret,enabled:!!d.enabled},rev());});}
function editRadiusSettings(){const r=state.radius;form('RADIUS authentication settings',`<div class="form-grid">${input('NAS identifier override (optional)','nas_identifier',r.nas_identifier??'')}${input('Advertised NAS IPv4 address (optional)','nas_ip_address',r.nas_ip_address??'')}${input('Response wait (seconds)','response_timeout_seconds',r.response_timeout_seconds,'number','min="1" max="60"')}${input('Attempts per server','attempts',r.attempts,'number','min="1" max="10"')}${input('EAP conversation limit (seconds)','exchange_timeout_seconds',r.exchange_timeout_seconds,'number','min="1" max="60"')}${input('Failed-cycle cooldown (simulation seconds)','failed_cycle_retry_seconds',r.failed_cycle_retry_seconds,'number','min="1" max="86400"')}${input('No-supplicant discovery (simulation seconds)','discovery_seconds',r.discovery_seconds,'number','min="1" max="3600"')}${input('Periodic reauthentication (simulation seconds, 0 = off)','reauthentication_seconds',r.reauthentication_seconds,'number','min="0" max="1000000"')}${input('Local inactivity limit (simulation seconds, 0 = off)','inactivity_seconds',r.inactivity_seconds,'number','min="0" max="1000000"')}${select('MAB username/password case','mab_case',opt('lower','Lowercase',r.mab_case==='lower')+opt('upper','Uppercase',r.mab_case==='upper'))}${select('MAB username/password separator','mab_separator',opt('','None',r.mab_separator==='')+opt(':','Colon',r.mab_separator===':')+opt('-','Hyphen',r.mab_separator==='-'))}${select('Station ID case','station_case',opt('lower','Lowercase',r.station_case==='lower')+opt('upper','Uppercase',r.station_case==='upper'))}${select('Station ID separator','station_separator',opt('','None',r.station_separator==='')+opt(':','Colon',r.station_separator===':')+opt('-','Hyphen',r.station_separator==='-'))}</div><p class="hint">Without an override, new exchanges use the switch name. Advertised IPv4 identity does not change a server's source binding. Protocol retries use real time; access timers use simulation time.</p>`,async f=>{const d=data(f),body:any={};for(const k of ['response_timeout_seconds','attempts','exchange_timeout_seconds','failed_cycle_retry_seconds','discovery_seconds','reauthentication_seconds','inactivity_seconds'])body[k]=Number(d[k]);for(const k of ['mab_case','mab_separator','station_case','station_separator'])body[k]=d[k];body.nas_identifier=d.nas_identifier===''?null:d.nas_identifier;body.nas_ip_address=d.nas_ip_address===''?null:d.nas_ip_address;await write('/radius/settings','PATCH',body,rev());});}
function editRadiusServer(id?:string,accounting=false){const r=state.radius,list=accounting?r.accounting.targets:r.servers,s=list.find((s:any)=>s.id===id);form(s?(accounting?'Edit accounting target':'Edit authentication server'):(accounting?'Add accounting target':'Add authentication server'),`<div class="form-grid">${input('Label','label',s?.label??'','text','required maxlength="80"')}${input('Server IP address','address',s?.address??'','text','required')}${input('UDP port','port',s?.port??(accounting?1813:1812),'number','min="1" max="65535" required')}${input('Source IP address (optional)','source_address',s?.source_address??'')}${input(s?'Shared secret (blank = unchanged)':'Shared secret','secret','','password',s?'':'required')}${input('Position in ordered list','position',s?list.findIndex((v:any)=>v.id===id)+1:list.length+1,'number','min="1" max="16"')}</div>${check('Enabled','enabled',s?.enabled??true)}<p class="hint">Source IP is an optional local bind address, not the advertised NAS IPv4 identity. In Docker bridge mode it must exist inside the container, not just on the Docker host. Leave blank for automatic source selection.</p>`,async f=>{const d=data(f);await write(accounting?'/radius/accounting/targets':'/radius/servers','POST',{...(id?{id}:{}),label:d.label,address:d.address,port:Number(d.port),source_address:d.source_address===''?null:d.source_address,secret:d.secret,enabled:!!d.enabled,position:Number(d.position)-1},rev());});}
function materialUsage(id:string){return {templates:values<any>(state.radius.templates).filter(t=>t.profile.trust_id===id||t.profile.client_identity_id===id).length,copies:values(state.endpoints).flatMap(e=>e.sources).filter(s=>s.supplicant?.trust_id===id||s.supplicant?.client_identity_id===id).length};}
function certificateSection(){return `<section id="radius-materials" class="certificate-section" aria-label="Certificates"><div class="card-head"><div><h2>Certificates</h2><p>CA trust and client identities used by supplicants.</p></div>${button('+ Add certificate','radius-material')}</div><div class="certificate-groups">${(['ca','client'] as const).map(kind=>`<div class="certificate-group"><h3>${kind==='ca'?'CA certificates':'Client certificates'}</h3>${values<any>(state.radius.materials).filter(m=>m.kind===kind).map(m=>{const uses=materialUsage(m.id);return `<div class="setting-row"><div><b>${esc(m.label)}</b><small>${esc(m.id.slice(0,8))} · ${kind==='ca'?'CA trust bundle':'Certificate + private key'}</small><small>${uses.templates} templates · ${uses.copies} copied source profiles</small></div><div class="row-buttons">${button('Edit','radius-material',m.id)}${button('Delete','radius-material-delete',m.id,'danger')}</div></div>`;}).join('')||'<p class="muted">None added.</p>'}</div>`).join('')}</div></section>`;}
function pemInput(label:string,name:string,limit:number){return `<div class="pem-input" data-pem="${name}">${select(label+' input',name+'_input',opt('file','Choose PEM file',true)+opt('paste','Paste PEM text'))}<label data-file>${label} file<input name="${name}_file" type="file" accept=".pem,.crt,.cer,.key,text/plain,application/x-pem-file"></label><label data-paste hidden>${label} PEM<textarea name="${name}" rows="5" maxlength="${limit}" spellcheck="false" autocomplete="off"></textarea></label><small class="hint">${Math.floor(limit/1024)} KiB maximum. PEM format.</small></div>`;}
function pemDraft(f:HTMLFormElement,name:string,limit:number):File|string{const mode=f.querySelector<HTMLSelectElement>(`[name=${name}_input]`)!.value;if(mode==='paste'){const value=(f.elements.namedItem(name) as HTMLTextAreaElement).value;if(new TextEncoder().encode(value).length>limit)throw Error('PEM input exceeds its size limit.');return value;}const file=(f.elements.namedItem(name+'_file') as HTMLInputElement).files?.[0];if(!file)return '';if(!file.size)throw Error('PEM file is empty.');if(file.size>limit)throw Error('PEM file exceeds its size limit.');return file;}
async function pemValue(draft:File|string){if(typeof draft==='string')return draft;try{return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await draft.arrayBuffer());}catch{throw Error('Could not read the PEM file as UTF-8 text. Choose it again or paste PEM text.');}}
function editRadiusMaterial(id?:string){const m=id?state.radius.materials[id]:undefined;form(m?'Edit certificate':'Add certificate',`${input('Label','label',m?.label??'','text','required maxlength="80"')}${m?`<p>${m.kind==='ca'?'CA trust bundle':'Client certificate and private key'} · ${esc(m.id.slice(0,8))}</p>`:select('Certificate purpose','kind',opt('ca','CA trust certificate / bundle',true)+opt('client','Client certificate and private key'))}${m?'<p class="hint">Saved contents stay unchanged unless you supply replacements. They are never displayed here.</p>':''}${pemInput('Certificate / chain','certificate',262144)}<div id="client-key-fields" ${m?.kind==='client'?'':'hidden'}>${pemInput('Private key','private_key',65536)}${input(m?'Key password (blank = unchanged)':'Key password (optional)','key_password','','password')}${check('Key has no password','clear_key_password',false)}</div><p class="hint">Choose or paste PEM files, then Save. Adding a certificate does not select it for a supplicant or change an existing trust choice.</p>`,async f=>{const d=data(f),kind=m?.kind??d.kind,revision=Number(dialog.dataset.revision);const certificateDraft=pemDraft(f,'certificate',262144),keyDraft=kind==='client'?pemDraft(f,'private_key',65536):'';const certificate=await pemValue(certificateDraft),privateKey=await pemValue(keyDraft);if(!dialog.open||!dialog.contains(f))return;if(!m&&!certificate)throw Error('Choose or paste a certificate.');if(!m&&kind==='client'&&!privateKey)throw Error('Choose or paste the matching private key.');const body:any={...(id?{id}:{}),kind,label:d.label};if(certificate)body.certificate=certificate;if(kind==='client'){if(privateKey)body.private_key=privateKey;if(d.clear_key_password)body.key_password=null;else if(d.key_password!=='')body.key_password=d.key_password;}await write('/radius/materials','POST',body,revision);});const f=dialog.querySelector('form')!;for(const group of f.querySelectorAll<HTMLElement>('.pem-input')){const mode=group.querySelector<HTMLSelectElement>('select')!;mode.addEventListener('change',()=>{group.querySelector<HTMLElement>('[data-file]')!.hidden=mode.value!=='file';group.querySelector<HTMLElement>('[data-paste]')!.hidden=mode.value!=='paste';});}f.querySelector<HTMLSelectElement>('[name=kind]')?.addEventListener('change',e=>{f.querySelector<HTMLElement>('#client-key-fields')!.hidden=(e.target as HTMLSelectElement).value!=='client';});}

function supplicantFields(profile:any,method:string){if(method==='none')return '<p class="hint">This source has no represented EAP supplicant. MAB remains a port-policy choice.</p>';const r=state.radius;return `<div class="form-grid">${input(method==='peap'?'Outer identity':'EAP identity','identity',profile?.identity??'','text','required')}${select('CA trust certificate','trust_id',opt('','Select a CA certificate',!profile?.trust_id)+values<any>(r.materials).filter(m=>m.kind==='ca').map(m=>opt(m.id,`${m.label} · ${m.id.slice(0,8)}`,m.id===profile?.trust_id)).join(''))}${input('Expected server DNS name','server_name',profile?.server_name??'','text','required')}${method==='tls'?select('Client certificate','client_identity_id',opt('','Select a client certificate',!profile?.client_identity_id)+values<any>(r.materials).filter(m=>m.kind==='client').map(m=>opt(m.id,`${m.label} · ${m.id.slice(0,8)}`,m.id===profile?.client_identity_id)).join('')):`${input('Inner username','username',profile?.username??'','text','required')}${input(profile?.has_password?'Password (blank = unchanged or template copy)':'Password','password',profile?.password??'','password')}`}</div>${!values<any>(r.materials).some(m=>m.kind==='ca')||method==='tls'&&!values<any>(r.materials).some(m=>m.kind==='client')?'<p class="hint">Add the required CA or client certificate in RADIUS → Certificates before saving this profile.</p>':''}`;}
function profileData(f:HTMLFormElement){const d=data(f);return {method:d.method,identity:d.identity,trust_id:d.trust_id,server_name:d.server_name,...(d.method==='tls'?{client_identity_id:d.client_identity_id}:{username:d.username,password:d.password})};}
function wireProfileFields(profile:any){const method=dialog.querySelector<HTMLSelectElement>('[name=method]')!;let draft={...profile,password:''};method.addEventListener('change',()=>{const current=data(dialog.querySelector('form')!);draft={...draft,...current,password:'',...(method.value==='tls'?{client_identity_id:''}:{})};dialog.querySelector('#profile-fields')!.innerHTML=supplicantFields(draft,method.value);});}
function editRadiusTemplate(id?:string){const t=id?state.radius.templates[id]:undefined,p=t?.profile;form(t?'Edit supplicant template':'Add supplicant template',`${input('Template label','label',t?.label??'','text','required maxlength="80"')}${select('Supplicant type','method',opt('tls','EAP-TLS',p?.method!=='peap')+opt('peap','PEAP-MSCHAPv2',p?.method==='peap'))}<div id="profile-fields">${supplicantFields(p,p?.method??'tls')}</div><p class="hint">Saving a template affects future copies, not existing clients.</p>`,async f=>{await write('/radius/templates','POST',{...(id?{id}:{}),label:data(f).label,profile:profileData(f)},rev());});wireProfileFields(p);}
function editSupplicant(eid:string,sid?:string){const e=state.endpoints[eid],s=e.sources.find(s=>s.id===sid)??e.sources[0];if(!s){toast('Add a source to this endpoint first.',true);return;}const profile=s.supplicant;form('Supplicant · '+esc(s.mac),`${select('Source','source_id',e.sources.map(s2=>opt(s2.id,s2.mac,s2.id===s.id)).join(''))}${select('Copy from template (optional)','template_id',opt('','Keep/edit this copy')+values<any>(state.radius.templates).map(t=>opt(t.id,`${t.label} · revision ${t.revision}`)).join(''))}${select('Supplicant type','method',opt('none','No supplicant',!profile)+opt('tls','EAP-TLS',profile?.method==='tls')+opt('peap','PEAP-MSCHAPv2',profile?.method==='peap'))}<div id="profile-fields">${supplicantFields(profile,profile?.method??'none')}</div>${check('Restart authentication after saving','restart',false)}<p class="hint">Save changes future authentication settings and preserves an existing grant. Restart ends the selected client/shared service without bouncing the link. Template copies and clones retain the selected credential identity until you explicitly change it.</p>`,async f=>{const d=data(f);const body:any={source_id:s.id,restart:!!d.restart,profile:d.method==='none'?null:profileData(f)};if(d.template_id&&d.method!=='none')body.template_id=d.template_id;await write(`/endpoints/${encodeURIComponent(eid)}/supplicant`,'POST',body,rev());});wireProfileFields(profile);dialog.querySelector<HTMLSelectElement>('[name=source_id]')!.addEventListener('change',e2=>{const id=(e2.target as HTMLSelectElement).value;dialog.close();editSupplicant(eid,id);});dialog.querySelector<HTMLSelectElement>('[name=template_id]')!.addEventListener('change',e2=>{const id=(e2.target as HTMLSelectElement).value;const selected=id?state.radius.templates[id].profile:profile;dialog.querySelector<HTMLSelectElement>('[name=method]')!.value=selected?.method??'none';dialog.querySelector('#profile-fields')!.innerHTML=supplicantFields(selected,selected?.method??'none');});}
function radiusSessionAction(id:string,action:string){const session=state.authentication_sessions.find(s=>s.id===id);if(!session)return;const p=state.ports[session.port_id];form(action==='restart'?'Restart authentication':'Reauthenticate session',`<p>${esc(session.mac)} on ${esc(p.name)}${p.authentication.host_mode==='multi-host'?' supplies the shared service for this port':''}.</p><p>${action==='restart'?'The current service ends and its temporary authorization is removed.':'Still-valid access remains during the renewal.'} Physical carrier is unchanged.</p>`,async()=>{await write(`/radius/sessions/${encodeURIComponent(id)}`,'POST',{action},rev());},action==='restart'?'Restart':'Reauthenticate');}
function editPort(id:string){
  const p=state.ports[id];let untaggedEdited=false;
  const parseVlans=(value:FormDataEntryValue)=>String(value).trim()?String(value).split(',').map(x=>Number(x.trim())):[];
  form(`Configure ${esc(p.name)}`,`<div class="form-grid">${input('Name','name',p.name)}${input('Alias','alias',p.alias)}${select('Attachment mode','mode',opt('direct','Direct · one endpoint',p.mode==='direct')+opt('shared','Shared · explicit partner',p.mode==='shared'))}${select('Ingress VLAN (PVID)','pvid',values(state.vlans).map(v=>opt(v.vid,`${v.vid} · ${v.name}`,p.pvid===v.vid)).join(''))}${input('Admitted VLANs (comma-separated)','admitted',p.admitted.join(', '))}${input('Untagged VLANs (comma-separated, optional)','untagged',p.untagged.join(', '))}${input('Forbidden VLANs (comma-separated, optional)','forbidden',p.forbidden.join(', '))}${input('Speed (bits/s)','speed',p.speed,'number','min="1"')}${input('MTU','mtu',p.mtu,'number','min="64" max="9216"')}</div><div class="form-grid">${select('Port access control','auth_control',opt('force-authorized','Force authorized',p.authentication.control==='force-authorized')+opt('auto','Automatic authentication',p.authentication.control==='auto')+opt('force-unauthorized','Force unauthorized',p.authentication.control==='force-unauthorized'))}${select('Authentication method','auth_method',opt('dot1x','802.1X only',p.authentication.method==='dot1x')+opt('mab','MAB only',p.authentication.method==='mab')+opt('dot1x-mab','802.1X → MAB',p.authentication.method==='dot1x-mab'))}${select('Authentication host mode','auth_host_mode',opt('single-host','Single host',p.authentication.host_mode==='single-host')+opt('multi-auth','Independent clients',p.authentication.host_mode==='multi-auth')+opt('multi-host','Shared service',p.authentication.host_mode==='multi-host'))}</div><div class="checks">${check('MAB fallback after no supplicant response','auth_no_supplicant',p.authentication.fallback_no_supplicant)}${check('MAB fallback after explicit EAP rejection','auth_reject',p.authentication.fallback_reject)}${check('Administrative enablement','admin_up',p.admin_up)}${check('Force link down','forced_down',p.forced_down)}${check('Shared link partner present','shared_partner',p.shared_partner)}${check('Send standard link notifications','link_notifications',p.link_notifications)}</div><p class="hint">PVID and untagged VLANs must be admitted; forbidden VLANs cannot be admitted. Changing PVID updates the old native membership unless you edit Untagged VLANs explicitly. Empty untagged and forbidden sets are supported.</p>`,async f=>{
    const d=data(f),payload:any={name:d.name,alias:d.alias,mode:d.mode,pvid:Number(d.pvid),admitted:parseVlans(d.admitted),forbidden:parseVlans(d.forbidden),speed:Number(d.speed),mtu:Number(d.mtu),admin_up:!!d.admin_up,forced_down:!!d.forced_down,shared_partner:!!d.shared_partner,link_notifications:!!d.link_notifications,authentication:{control:d.auth_control,method:d.auth_method,host_mode:d.auth_host_mode,fallback_no_supplicant:!!d.auth_no_supplicant,fallback_reject:!!d.auth_reject}};
    if(untaggedEdited)payload.untagged=parseVlans(d.untagged);
    await write(`/ports/${id}`,'PATCH',payload,rev());
  });
  const pvid=dialog.querySelector<HTMLSelectElement>('[name=pvid]')!,untagged=dialog.querySelector<HTMLInputElement>('[name=untagged]')!;
  untagged.addEventListener('input',()=>{untaggedEdited=true;});
  pvid.addEventListener('change',()=>{
    if(!untaggedEdited){const next=Number(pvid.value);untagged.value=(next===p.pvid?p.untagged:[...new Set([...p.untagged.filter(v=>v!==p.pvid),next])].sort((a,b)=>a-b)).join(', ');}
  });
}
function sourceRow(s?:Source){return `<div class="source-row" data-source-id="${esc(s?.id??'')}">${input('MAC address','mac',s?.mac??'','text','required placeholder="02:00:00:00:00:10"')}${input('Tag / untagged','tag',s?.tag??'untagged')}${input('First delay (ms)','delay',s?.initial_delay_ms??1000,'number','min="1" required')}${input('Interval (ms)','interval',s?.interval_ms??30000,'number','min="1" required')}${input('Frame octets','octets',s?.octets??64,'number','min="64" max="9216" required')}<button type="button" class="remove-source danger" aria-label="Remove source">×</button></div>`;}
function editEndpoint(id?:string){const e=id?state.endpoints[id]:undefined;form(e?'Edit endpoint':'Create endpoint',`${input('Display name','name',e?.name??'','text','required maxlength="255"')}${check('Active source activity (unchecked = silent)','active',e?.active??true)}<div class="section-label">SOURCE DEFINITIONS</div><p class="hint">Explicit tags can reference absent VLANs. Live edits preserve cached addresses and do not flap the link.</p><div id="source-rows">${e?e.sources.map(s=>sourceRow(s)).join(''):sourceRow()}</div><button type="button" id="add-source">+ Add source</button><label class="metadata">Metadata (JSON object, optional)<textarea name="metadata" rows="3">${esc(JSON.stringify(e?.metadata??{},null,2))}</textarea></label>`,async f=>{const d=data(f);const sources=[...f.querySelectorAll<HTMLElement>('.source-row')].map(row=>{const v=(name:string)=>row.querySelector<HTMLInputElement>(`[name=${name}]`)!.value;const source:any={mac:v('mac'),tag:v('tag')==='untagged'?'untagged':Number(v('tag')),initial_delay_ms:Number(v('delay')),interval_ms:Number(v('interval')),octets:Number(v('octets'))};if(row.dataset.sourceId)source.id=row.dataset.sourceId;return source;});await write(id?`/endpoints/${id}`:'/endpoints',id?'PATCH':'POST',{name:d.name,active:!!d.active,metadata:JSON.parse(String(d.metadata)),sources},rev());},e?'Save endpoint':'Create endpoint');
  dialog.querySelector('#add-source')!.addEventListener('click',()=>dialog.querySelector('#source-rows')!.insertAdjacentHTML('beforeend',sourceRow()));
}
function attachment(id?:string,port?:string){const eps=values(state.endpoints);if(!eps.length){editEndpoint();return;}form('Attach or move endpoint',`${select('Endpoint','endpoint',eps.map(e=>opt(e.id,e.name,e.id===id)).join(''))}${select('Destination port','port',values(state.ports).map(p=>opt(p.id,`${p.name} · ${p.mode} · ${p.attachments.length} attached`,p.id===(port??state.attachments[id??'']))).join(''))}<p class="hint">Moving validates the destination before changing the current attachment. Direct ports accept one endpoint.</p>${id&&state.attachments[id]?'<button type="button" id="detach" class="danger">Disconnect endpoint</button>':''}`,async f=>{const d=data(f);await write(`/endpoints/${d.endpoint}/attachment`,'PUT',{port_id:d.port},rev());},'Connect endpoint');
  dialog.querySelector('#detach')?.addEventListener('click',async()=>{try{await write(`/endpoints/${id}/attachment`,'DELETE',{},rev());dialog.close();await refresh();toast('Endpoint disconnected');}catch(e){toast((e as Error).message,true);}});
}
function editSwitchSettings(){const s=state.switch;form('Switch settings',`<div class="form-grid">${input('System name','name',s.name)}${input('Contact','contact',s.contact)}${input('Location','location',s.location)}${input('Bridge base MAC','base_mac',s.base_mac)}${input('Aging time (seconds)','aging_seconds',s.aging_seconds,'number','min="10" max="1000000"')}${input('Dynamic FDB capacity','fdb_limit',s.fdb_limit,'number','min="1" max="100000"')}</div>`,async f=>{const d=data(f);await write('/switch','PATCH',{name:d.name,contact:d.contact,location:d.location,base_mac:d.base_mac,aging_seconds:Number(d.aging_seconds),fdb_limit:Number(d.fdb_limit)},rev());});}
function editIdentity(){const s=state.switch;form('SNMP identity',`<div class="form-grid">${input('System object ID (sysObjectID)','oid',s.identity.sys_object_id??'','text','placeholder="Full numeric OID"')}${input('System description','descr',s.identity.sys_descr)}${select('Legacy BRIDGE-MIB VLAN','legacy_vlan',values(state.vlans).map(v=>opt(v.vid,`${v.vid} · ${v.name}`,v.vid===s.legacy_vlan)).join(''))}${input('Notification queue capacity','queue_limit',s.queue_limit,'number','min="1" max="10000"')}</div><p class="hint">Use a full numeric OID. It changes advertised identity only. Leaving it blank disables listening and all notification sends; simulation stays available.</p>`,async f=>{const d=data(f);await write('/switch','PATCH',{identity:{sys_descr:d.descr,sys_object_id:d.oid||null},legacy_vlan:Number(d.legacy_vlan),queue_limit:Number(d.queue_limit)},rev());});}
function credentialData(d:Record<string,FormDataEntryValue>){
  const payload:any={label:d.label,version:d.version};
  if(d.version==='2c'){if(d.community)payload.community=d.community;}
  else{payload.username=d.username;payload.security_level=d.security_level;if(d.auth_key)payload.auth_key=d.auth_key;if(d.priv_key)payload.priv_key=d.priv_key;}
  return payload;
}
function credentialProtocol(container:HTMLElement,version:string,c?:any){
  if(version==='2c'){container.innerHTML=input('Community','community','','password','autocomplete="new-password"');return;}
  container.innerHTML=`${input('Username','username',c?.username??'')}${select('Protection profile','security_level',['noAuthNoPriv','authNoPriv','authPriv'].map(v=>opt(v,v,v===(c?.security_level??'authPriv'))).join(''))}<div class="credential-keys form-grid"></div>`;
  const level=container.querySelector<HTMLSelectElement>('[name=security_level]')!;
  const keys=container.querySelector<HTMLDivElement>('.credential-keys')!;
  const renderKeys=()=>{keys.innerHTML=(level.value!=='noAuthNoPriv'?input('SHA-256 passphrase','auth_key','','password','autocomplete="new-password"'):'')+(level.value==='authPriv'?input('AES-128 passphrase','priv_key','','password','autocomplete="new-password"'):'');};
  level.addEventListener('change',renderKeys);renderKeys();
}
function accessEditor(container:HTMLElement,policy:any){
  const saved=policy??defaultAccess();
  container.innerHTML=select('Access','access_mode',['none','read','read-write','write'].map(m=>opt(m,{'none':'None (traps only)','read':'Read','read-write':'Read/write','write':'Write only'}[m],m===accessMode(saved))).join(''))+
    (['polling','writing'] as const).map(use=>{
      const p=saved[use],label=use==='polling'?'Read':'Write',views=values(state.views);
      const options=(use==='writing'?opt('','Select a view',p.view_id===null):'')+(p.view_id!==null&&!views.some(v=>v.id===p.view_id)?opt(p.view_id,`Missing view · ${p.view_id}`,true):'')+views.map(v=>opt(v.id,v.name,v.id===p.view_id)).join('');
      return `<div data-access-section="${use}" class="form-grid">${select(`${label} view`,`${use}_view`,options)}${input(`${label} source networks (optional)`,`${use}_networks`,p.networks.join(', '))}</div>`;
    }).join('')+'<p class="hint">Read and write views and source networks are independent. Empty networks mean no source-IP restriction. Trap destinations are unchanged.</p>';
  const mode=container.querySelector<HTMLSelectElement>('[name=access_mode]')!;
  const active=(use:string)=>use==='polling'?['read','read-write'].includes(mode.value):['write','read-write'].includes(mode.value);
  const show=()=>container.querySelectorAll<HTMLElement>('[data-access-section]').forEach(el=>el.style.display=active(el.dataset.accessSection!)?'':'none');
  mode.addEventListener('change',show);show();
  return ()=>{
    const result:any={};
    for(const use of ['polling','writing'] as const){
      const before=saved[use],enabled=active(use),patch:any={};
      if(enabled!==before.enabled)patch.enabled=enabled;
      if(enabled){
        const value=container.querySelector<HTMLSelectElement>(`[name=${use}_view]`)!.value;
        const view_id=use==='writing'?(value||null):value;
        const networks=container.querySelector<HTMLInputElement>(`[name=${use}_networks]`)!.value.split(',').map(v=>v.trim()).filter(Boolean);
        if(view_id!==before.view_id)patch.view_id=view_id;
        if(JSON.stringify(networks)!==JSON.stringify(before.networks))patch.networks=networks;
      }
      if(Object.keys(patch).length)result[use]=patch;
    }
    return result;
  };
}
function editCredential(id?:string,initialVersion='2c'){
  const c=id?state.credentials[id]:undefined,consumers=c?values(state.targets).filter(t=>t.credential_id===id):[];
  let readAccess=()=>({});
  form(c?'Edit credential':initialVersion==='3'?'Add user':'Add community',`${c?`<p>Trap destinations: ${esc(consumers.map(t=>`${t.address}:${t.port}`).join(', ')||'none')}.</p>`:''}<div class="form-grid">${input('Label','label',c?.label??'','text','required')}${select('SNMP version','version',opt('2c','v2c',(c?.version??initialVersion)==='2c')+opt('3','v3',(c?.version??initialVersion)==='3'))}</div><div id="credential-protocol" class="form-grid"></div><div id="credential-access"></div>${check('Credential enabled','enabled',c?.enabled??true)}<p class="hint">Blank secret fields preserve existing secrets when editing the same SNMP version.</p>`,async f=>{
    const d=data(f),payload:any={...credentialData(d),enabled:!!d.enabled};
    const converting=!!c&&d.version!==c.version;
    if(d.version==='3'){
      const choice=String(d.group_choice);
      if(converting&&choice==='')throw Error('Choose incoming access for the protocol change.');
      if(choice==='keep')payload.access_transfer='keep';
      else if(converting&&choice==='none')payload.access_transfer='none';
      else{
        const group_id=choice==='none'?null:choice.slice(6);
        if(converting||!c||group_id!==c.group_id)payload.group_id=group_id;
      }
    }else if(converting){
      if(!d.access_transfer)throw Error('Choose incoming access for the protocol change.');
      payload.access_transfer=d.access_transfer;
    }else Object.assign(payload,readAccess());
    await write(id?`/snmp/credentials/${id}`:'/snmp/credentials',id?'PUT':'POST',payload,rev());
  });
  const protocol=dialog.querySelector<HTMLDivElement>('#credential-protocol')!,version=dialog.querySelector<HTMLSelectElement>('[name=version]')!,access=dialog.querySelector<HTMLDivElement>('#credential-access')!;
  function renderAccess(){
    const converting=!!c&&version.value!==c.version;
    if(version.value==='3'){
      const selected=converting?'':c?.group_id?`group:${c.group_id}`:'none';
      access.innerHTML=select('Group','group_choice',(converting?opt('','Choose incoming access',true)+opt('keep','Keep current access (create group)'):'')+opt('none','None (traps only)',selected==='none')+values(state.groups).map(g=>opt(`group:${g.id}`,`${g.label} · ${accessLabel(g)} · minimum ${g.minimum_security_level}`,selected===`group:${g.id}`)).join(''))+'<p class="hint" id="group-profile-hint"></p>';
      const group=access.querySelector<HTMLSelectElement>('[name=group_choice]')!;
      group.required=converting;
      const hint=()=>{
        const profile=protocol.querySelector<HTMLSelectElement>('[name=security_level]')!.value,g=state.groups[group.value.slice(6)],levels=['noAuthNoPriv','authNoPriv','authPriv'];
        access.querySelector('#group-profile-hint')!.textContent=g&&levels.indexOf(profile)<levels.indexOf(g.minimum_security_level)?"This user's protection profile does not meet the group's minimum; incoming management is unavailable.":group.value==='keep'?'Creates a group from the saved community access, with this protection profile as its minimum.':'Incoming management uses this protection profile. A lower group minimum does not relax it. No group means no incoming access; traps remain independent.';
      };
      group.addEventListener('change',hint);protocol.onchange=hint;hint();
    }else{
      protocol.onchange=null;
      if(converting){
        access.innerHTML=select('Incoming access','access_transfer',opt('','Choose incoming access',true)+opt('keep','Keep current access')+opt('none','None (traps only)'))+'<p class="hint">Keeping access copies the saved group policy into this community. Community-based access has no USM minimum and can become usable even when the old user profile did not meet its group minimum. Other users and groups are unchanged.</p>';
        access.querySelector<HTMLSelectElement>('[name=access_transfer]')!.required=true;
      }else readAccess=accessEditor(access,c);
    }
  }
  const renderProtocol=()=>{credentialProtocol(protocol,version.value,c?.version===version.value?c:undefined);renderAccess();};
  version.addEventListener('change',renderProtocol);renderProtocol();
}
function editGroup(id?:string){
  const g=id?state.groups[id]:undefined,members=values(state.credentials).filter(c=>c.version==='3'&&c.group_id===id);
  let readAccess=()=>({});
  form(g?'Edit group':'Add group',`${input('Label','label',g?.label??'','text','required')}${select('Minimum protection','minimum_security_level',['noAuthNoPriv','authNoPriv','authPriv'].map(v=>opt(v,v,v===(g?.minimum_security_level??'authPriv'))).join(''))}<div id="group-access"></div><p>Members: ${esc(members.map(c=>`${c.label} (${c.security_level}${c.enabled?'':', disabled'})`).join(', ')||'none')}.</p><p class="hint" id="group-members-hint"></p><p class="hint">Changes apply to every member. Each user keeps its configured protection profile; a lower group minimum does not enable weaker requests.</p>`,async f=>{
    const d=data(f);await write(id?`/snmp/groups/${id}`:'/snmp/groups',id?'PUT':'POST',{label:d.label,minimum_security_level:d.minimum_security_level,...readAccess()},rev());
  });
  readAccess=accessEditor(dialog.querySelector<HTMLDivElement>('#group-access')!,g);
  const minimum=dialog.querySelector<HTMLSelectElement>('[name=minimum_security_level]')!;
  const showMismatch=()=>{
    const levels=['noAuthNoPriv','authNoPriv','authPriv'],below=members.filter(c=>levels.indexOf(c.security_level)<levels.indexOf(minimum.value));
    dialog.querySelector('#group-members-hint')!.textContent=below.length?`Below selected minimum: ${below.map(c=>c.label).join(', ')}. These users cannot use this group's incoming access.`:'';
  };
  minimum.addEventListener('change',showMismatch);showMismatch();
}
function editTarget(id?:string){
  const t=id?state.targets[id]:undefined,initial=t?state.credentials[t.credential_id]:undefined;
  form(t?'Edit target':'Add notification target',`<div class="form-grid">${input('Destination IP address','address',t?.address??'127.0.0.1','text','required')}${input('UDP port','port',t?.port??162,'number','min="1" max="65535"')}${select('SNMP version','version',opt('2c','v2c',initial?.version!=='3')+opt('3','v3',initial?.version==='3'))}${select('Credential','credential_mode',opt('existing','Select existing')+opt('new','Create new'))}</div><div id="target-credential"></div>${input('Optional source IP binding','source_address',t?.source_address??'')}<div class="checks">${check('Target enabled','enabled',t?.enabled??true)}${['coldStart','linkUp','linkDown'].map(kind=>check(kind,kind,t?.types.includes(kind)??true)).join('')}</div>`,async f=>{
    const d=data(f);const payload:any={address:d.address,port:Number(d.port),source_address:d.source_address||null,enabled:!!d.enabled,types:['coldStart','linkUp','linkDown'].filter(k=>d[k])};
    if(d.credential_mode==='new')payload.new_credential=credentialData(d);else payload.credential_id=d.credential_id;
    await write(id?`/notifications/targets/${id}`:'/notifications/targets',id?'PUT':'POST',payload,rev());
  });
  const version=dialog.querySelector<HTMLSelectElement>('[name=version]')!,mode=dialog.querySelector<HTMLSelectElement>('[name=credential_mode]')!,fields=dialog.querySelector<HTMLDivElement>('#target-credential')!;
  function renderChoice(){
    const choices=values(state.credentials).filter(c=>c.version===version.value);
    if(!choices.length)mode.value='new';
    if(mode.value==='existing')fields.innerHTML=select('Saved credential','credential_id',choices.map(c=>opt(c.id,`${c.label}${c.enabled?'':' (disabled)'}`,c.id===t?.credential_id)).join(''));
    else{
      fields.innerHTML=`${input('Label','label','','text','required')}<div class="inline-protocol form-grid"></div><p class="hint">The new credential is reusable. New communities have no incoming access; new users have no group.</p>`;
      // This fragment is recreated on every version/mode change; unsaved keys are not carried over.
      credentialProtocol(fields.querySelector<HTMLDivElement>('.inline-protocol')!,version.value);
    }
  }
  mode.addEventListener('change',renderChoice);version.addEventListener('change',renderChoice);renderChoice();
}

document.addEventListener('click',e=>{if(!simulation()?.contains(e.target as Node))closeSimulation();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&simulation()?.open){e.preventDefault();closeSimulation(true);}});
app.addEventListener('input',e=>{if((e.target as HTMLElement).id==='search'){search=(e.target as HTMLInputElement).value;const pos=(e.target as HTMLInputElement).selectionStart;render();const el=document.querySelector<HTMLInputElement>('#search')!;el.focus();el.setSelectionRange(pos,pos);}});
dialog.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest('.remove-source');if(target)target.closest('.source-row')?.remove();});
dialog.addEventListener('close',()=>{if(ready)void refresh();});
app.addEventListener('click',async e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!target)return;const a=target.dataset.action!,id=target.dataset.id!;try{
  if(a==='nav'){closeSimulation();page=id;search='';render();}
  else if(a==='select-port'){selected=id;render();}
  else if(a==='new-endpoint')editEndpoint();else if(a==='edit-endpoint')editEndpoint(id);else if(a==='edit-port')editPort(id);
  else if(a==='attachment')attachment(id);else if(a==='attach-port')attachment(undefined,id);
  else if(a==='detach'){if(disconnecting.has(id))return;disconnecting.add(id);render();try{await write(`/endpoints/${id}/attachment`,'DELETE');toast('Endpoint disconnected');}finally{disconnecting.delete(id);render();}}
  else if(a==='switch-settings')editSwitchSettings();else if(a==='identity')editIdentity();else if(a==='credential')editCredential(id||undefined);else if(a==='user')editCredential(undefined,'3');else if(a==='group')editGroup(id||undefined);else if(a==='target')editTarget(id||undefined);
  else if(a==='accounting-settings')editAccountingSettings();
  else if(a==='accounting-target')editRadiusServer(id||undefined,true);
  else if(a==='dynamic-settings')editDynamicSettings();
  else if(a==='dynamic-sender')editDynamicSender(id||undefined);
  else if(a==='accounting-target-delete'||a==='dynamic-sender-delete'){form('Delete RADIUS destination','<p>Queued work using this configuration is canceled; other grants are retained.</p>',async()=>{await write(a==='accounting-target-delete'?`/radius/accounting/targets/${encodeURIComponent(id)}`:`/radius/dynamic/senders/${encodeURIComponent(id)}`,'DELETE',{},rev());},'Delete');}
  else if(a==='radius-settings')editRadiusSettings();
  else if(a==='radius-server')editRadiusServer(id||undefined);
  else if(a==='radius-material')editRadiusMaterial(id||undefined);
  else if(a==='radius-template')editRadiusTemplate(id||undefined);
  else if(a==='supplicants')editSupplicant(id);
  else if(a==='radius-restart'||a==='radius-reauthenticate')radiusSessionAction(id,a==='radius-restart'?'restart':'reauthenticate');
  else if(a==='radius-server-delete'||a==='radius-material-delete'||a==='radius-template-delete'){const family=a==='radius-server-delete'?'servers':a==='radius-material-delete'?'materials':'templates';form('Delete RADIUS record','<p>Existing references must be removed first. Other records and credentials are retained.</p>',async()=>{await write(`/radius/${family}/${encodeURIComponent(id)}`,'DELETE',{},rev());},'Delete');}
  else if(a==='pause'||a==='resume')await write('/clock/'+a,'POST');
  else if(a==='cancel-advance'){await write(`/clock/advance/${id}/cancel`,'POST');toast('Remaining advance canceled');}
  else if(a==='advance1'){if(!state.paused)throw Error('Pause the clock before manual advancement.');const result=await write('/clock/advance','POST',{duration_ms:1000});if(result.advance?.status==='waiting')toast('Advance waiting for authentication');}
  else if(a==='advance'){if(!state.paused)throw Error('Pause the clock before manual advancement.');closeSimulation(true);form('Advance simulation time',input('Duration (milliseconds)','duration',1000,'number','min="1" max="86400000"'),async f=>{const result=await write('/clock/advance','POST',{duration_ms:Number(data(f).duration)},rev());return result.advance?.status==='waiting'?'Advance waiting for authentication':'Advance completed';},'Advance & drain due work');}
  else if(a==='clone')form('Clone endpoint',`${input('Display name','name',state.endpoints[id].name+' copy')}${check('Preserve MACs for duplication testing','preserve_macs',false)}`,async f=>{const d=data(f);await write(`/endpoints/${id}/clone`,'POST',{name:d.name,preserve_macs:!!d.preserve_macs},rev());},'Clone endpoint');
  else if(a==='new-vlan'||a==='edit-vlan')form(a==='new-vlan'?'Add VLAN':'Rename VLAN',`${a==='new-vlan'?input('VLAN ID','vid','','number','min="1" max="4094" required'):''}${input('Name','name',state.vlans[id]?.name??'')}`,async f=>{const d=data(f);await write(a==='new-vlan'?'/vlans':`/vlans/${id}`,a==='new-vlan'?'POST':'PATCH',a==='new-vlan'?{vid:Number(d.vid),name:d.name}:{name:d.name},rev());});
  else if(a==='delete-vlan'){const p=await api(`/vlans/${id}/deletion-preview`);form(`Delete VLAN ${id}`,`<p>These ingress PVIDs fall back to VLAN 1:</p><p><b>${esc(p.fallback_ports.join(', ')||'None')}</b></p><p>Membership is removed from:</p><p><b>${esc(p.membership_ports.join(', ')||'None')}</b></p><p class="hint">Only learning in the deleted FDB is removed. Explicit endpoint tags remain unchanged.</p>`,async()=>{await write(`/vlans/${id}`,'DELETE',{},rev());},'Delete VLAN');dialog.dataset.revision=String(p.configuration_revision);}
  else if(a==='delete-endpoint'||a==='delete-credential'||a==='delete-target'||a==='delete-view'||a==='delete-group'){const route=({'delete-endpoint':'endpoints','delete-credential':'snmp/credentials','delete-target':'notifications/targets','delete-view':'snmp/views','delete-group':'snmp/groups'} as any)[a];form('Delete saved record','<p>This removes the selected configuration record. Referenced credentials, groups, views, and attached endpoints must be disconnected first.</p>',async()=>{await write(`/${route}/${id}`,'DELETE',{},rev());},'Delete record');}
  else if(a==='clear')form('Clear learned addresses',`${select('Port scope','port',opt('','All ports')+values(state.ports).map(p=>opt(p.id,p.name)).join(''))}${select('VLAN scope','vid',opt('','All VLANs')+values(state.vlans).map(v=>opt(v.vid,`${v.vid} · ${v.name}`)).join(''))}<p class="hint">Matching cached entries are removed and pending learning invalidated. Active sources can relearn after their initial delay.</p>`,async f=>{const d=data(f);await write('/fdb/clear','POST',{port_id:d.port||null,vid:d.vid?Number(d.vid):null},rev());},'Clear matching entries');
  else if(a==='snmp')form('SNMP listener',`${check('Enable SNMP','enabled',state.snmp.enabled)}<div class="form-grid">${input('Listen IP address','host',state.snmp.host)}${input('UDP port','port',state.snmp.port,'number','min="1" max="65535"')}${input('Maximum response varbinds','max_varbinds',state.snmp.max_varbinds,'number','min="1" max="1000"')}</div><p class="hint">The listener starts when enabled with identity and an enabled community or user with read or write access. New Docker configurations use 0.0.0.0; native configurations use 127.0.0.1. Saved addresses are retained. Docker uses the same port as Compose (161 by default).</p>`,async f=>{const d=data(f);await write('/snmp/settings','PATCH',{enabled:!!d.enabled,host:d.host,port:Number(d.port),max_varbinds:Number(d.max_varbinds)},rev());});
  else if(a==='view'){const v=state.views[id];form(v?'Edit OID view':'Add OID view',`${input('Name','name',v?.name??'')}${input('Included numeric OID prefixes (comma-separated)','includes',v?.includes.join(', ')??'1.3.6.1.2.1')}`,async f=>{const d=data(f);await write(id?`/snmp/views/${id}`:'/snmp/views',id?'PUT':'POST',{...(id?{id}:{}),name:d.name,includes:String(d.includes).split(',').map(v=>v.trim())},rev());});}
  else if(a==='test-target'){await write(`/notifications/targets/${id}/test`,'POST');toast('Test coldStart queued. See event history for send status.');}
  else if(a==='reboot')form('Reboot switch','<p>Clear learned addresses, reset counters and management uptime, and restart source delays. Configuration, attachments and clock mode are preserved.</p>',async()=>{await write('/switch/reboot','POST',{},rev());},'Reboot switch');
  else if(a==='export'){const scenario=await api('/scenarios/export');const url=URL.createObjectURL(new Blob([JSON.stringify(scenario,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='switchlab-scenario.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  else if(a==='import')form('Import lab scenario',`<label>Scenario JSON<input name="file" type="file" accept=".json" required></label><p class="hint">Use an export from this switch. The entire scenario is validated before replacement. Deployment identity, credentials and targets are preserved.</p>`,async f=>{const file=(f.querySelector('[name=file]') as HTMLInputElement).files![0];if(file.size>8*1024*1024)throw Error('File exceeds 8 MiB');await write('/scenarios/import','POST',{scenario:JSON.parse(await file.text())},rev());},'Validate & import');
  else if(a==='logout'){await api('/auth/logout','POST',{});ready=false;await authenticate();}
}catch(err){toast((err as Error).message,true);}});

void authenticate().catch(e=>toast(e.message,true));
setInterval(()=>{if(ready&&!dialog.open&&document.activeElement?.tagName!=='INPUT')void refresh().catch(e=>toast(e.message,true));},1500);

